-- 分阶段淘汰试验；Bootstrap schema is also generated by SQLAlchemy Base.metadata.create_all.
CREATE TABLE IF NOT EXISTS trials(id SERIAL PRIMARY KEY,title VARCHAR(120) UNIQUE NOT NULL,lot VARCHAR(60) NOT NULL,stage_size INTEGER NOT NULL,budget INTEGER NOT NULL,alpha FLOAT NOT NULL,max_stages INTEGER NOT NULL,current_stage INTEGER NOT NULL,status VARCHAR(20) NOT NULL,finish_reason TEXT NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS trial_processes(id SERIAL PRIMARY KEY,trial_id INTEGER NOT NULL REFERENCES trials(id),process_id INTEGER NOT NULL REFERENCES processes(id),status VARCHAR(20) NOT NULL,eliminated_stage INTEGER,rationale TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trial_stages(id SERIAL PRIMARY KEY,trial_id INTEGER NOT NULL REFERENCES trials(id),stage_no INTEGER NOT NULL,status VARCHAR(20) NOT NULL,z_bound FLOAT NOT NULL,test_alpha FLOAT NOT NULL,decisions JSON,sealed_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS trial_orders(id SERIAL PRIMARY KEY,code VARCHAR(60) UNIQUE NOT NULL,trial_id INTEGER NOT NULL REFERENCES trials(id),stage_no INTEGER NOT NULL,process_id INTEGER NOT NULL REFERENCES processes(id),status VARCHAR(20) NOT NULL,claimed_by VARCHAR(120) NOT NULL,claimed_at VARCHAR(40) NOT NULL,reported_at VARCHAR(40) NOT NULL,sample_id INTEGER REFERENCES samples(id));
